//! Polish lexical respelling — a bit-parity port of
//! loudkit.frontend.polish.lexical_respelling (Python), respell.ts (JS) and
//! speechtext/respell.go (Go) — the Swift engine's `LexicalRespelling`.
//!
//! English words embedded in Polish text are respelled the way a Polish reader
//! says them: "download" → "dałnloud", "deadline'u" → "dedlajnu". Numbers
//! become Polish cardinals, acronyms are spelled with Polish letter names, code
//! tokens are spelled out, and inflected loanwords are matched by stem + known
//! Polish ending. The 110k CMUdict long tail is generated by
//! tools/gen_pl_respell.py and embedded here with `include_str!`.

use std::collections::{HashMap, HashSet};
use std::sync::LazyLock;

use regex::Regex;

use crate::speechtext::{ascii_digits, is_decimal_digit};

/// The generated lexicon, embedded at compile time (Go uses `//go:embed`,
/// JS loads it lazily; all three ship the same generated file).
static RESPEL_JSON: &str = include_str!("pl_en_respell.json");

static PAYLOAD: LazyLock<Payload> =
    LazyLock::new(|| serde_json::from_str(RESPEL_JSON).expect("embedded respell JSON is valid"));

#[derive(serde::Deserialize)]
struct Payload {
    respell: HashMap<String, String>,
    words: Vec<String>,
    #[serde(rename = "respellAll")]
    respell_all: HashMap<String, String>,
    polish: Vec<String>,
}

static POLISH_SET: LazyLock<HashSet<String>> =
    LazyLock::new(|| PAYLOAD.polish.iter().cloned().collect());
static WORDS_SET: LazyLock<HashSet<String>> =
    LazyLock::new(|| PAYLOAD.words.iter().cloned().collect());

// Multi-word anglicisms respelled as a unit, BEFORE the word pass — "release
