// Math and unit symbols the model cannot say, as Polish words — with context
// guards, because "-" is also a hyphen and "/" is also a path. Rust's regex
// has no lookbehind, so "preceded by a digit" is a capturing group restored
// by the replacement.
const RESPEL_SYMBOL_RULES: &[(&str, &str)] = &[
    (r"(\d)\s?%", "${1} procent"),
    (r"(\d)\s?°C", "${1} stopni Celsjusza"),
    (r"(\d)\s?°", "${1} stopni"),
    (r"(\d)\s*/\s*(\d)", "${1} przez ${2}"),
    (r"(\d)\s*\*\s*(\d)", "${1} razy ${2}"),
    (r"(\d)\s*\^\s*(\d)", "${1} do potęgi ${2}"),
    (r"\s=\s", " równa się "),
    (r"\s\+\s", " plus "),
    (r"\s<\s", " mniejsze niż "),
    (r"\s>\s", " większe niż "),
    (r"\s-\s", " minus "),
];

static KEEP_POLISH_SET: LazyLock<HashSet<String>> =
    LazyLock::new(|| KEEP_POLISH.split_whitespace().map(String::from).collect());
static WORD_ACRONYMS_SET: LazyLock<HashSet<String>> =
    LazyLock::new(|| WORD_ACRONYMS.split_whitespace().map(String::from).collect());
static POLISH_FUNCTION_SET: LazyLock<HashSet<String>> = LazyLock::new(|| {
    POLISH_FUNCTION_WORDS
        .split_whitespace()
        .map(String::from)
        .collect()
});
static ENDINGS_SET: LazyLock<HashSet<&'static str>> =
    LazyLock::new(|| POLISH_ENDINGS.iter().copied().collect());
static LEXICON_MAP: LazyLock<HashMap<String, String>> = LazyLock::new(|| {
    LEXICON
        .iter()
        .map(|(a, b)| (a.to_string(), b.to_string()))
        .collect()
});
static RESPEL_SYMBOL_RES: LazyLock<Vec<(Regex, &'static str)>> = LazyLock::new(|| {
    RESPEL_SYMBOL_RULES
        .iter()
        .map(|(p, r)| (Regex::new(p).unwrap(), *r))
        .collect()
});

fn generated() -> &'static HashMap<String, String> {
    &PAYLOAD.respell
}

fn respell_all() -> &'static HashMap<String, String> {
    &PAYLOAD.respell_all
}

fn is_english_word(lower: &str) -> bool {
    WORDS_SET.contains(lower)
}

fn lookup(word: &str) -> Option<String> {
    if let Some(v) = LEXICON_MAP.get(word) {
        return Some(v.clone());
    }
    if KEEP_POLISH_SET.contains(word) {
        return None;
    }
    generated().get(word).cloned()
}

fn spelled_acronym(word: &str) -> Option<String> {
    let n = word.chars().count();
    if !(2..=5).contains(&n) {
        return None;
    }
    if !word.chars().all(|c| c.is_ascii_uppercase()) {
        return None;
    }
    let lower = word.to_lowercase();
    if WORD_ACRONYMS_SET.contains(&lower) {
        return Some(lower);
    }
    let names: Vec<&str> = lower
        .chars()
        .map(|c| {
            let s = c.to_string();
            LETTER_NAMES.iter().find(|(l, _)| *l == s).map(|(_, r)| *r)
        })
        .collect::<Option<Vec<_>>>()?;
    Some(names.join("-"))
}

fn under1000(n: usize) -> Vec<&'static str> {
    let mut parts = Vec::new();
    if n >= 100 {
        parts.push(HUNDREDS[n / 100]);
    }
    let rest = n % 100;
    if (10..=19).contains(&rest) {
        parts.push(TEENS[rest - 10]);
    } else {
        if rest >= 20 {
            parts.push(TENS[rest / 10]);
        }
        if !rest.is_multiple_of(10) {
            parts.push(UNITS[rest % 10]);
        }
    }
    parts
}

fn number_words(token: &str) -> Option<String> {
    if token.chars().count() > 6 {
        return None;
    }
    if token.starts_with('0') && token != "0" {
        return None;
    }
    if !token.chars().all(is_decimal_digit) {
        return None;
    }
    // Through `ascii_digits` because `str::parse` reads ASCII digits only:
    // `"١٢٣"` is a number to Python's `int()` and to this function.
    let value: usize = ascii_digits(token)?.parse().ok()?;
    if value == 0 {
        return Some("zero".to_string());
    }
    let mut parts = Vec::new();
    let thousands = value / 1000;
    if thousands > 0 {
        if thousands == 1 {
            parts.push("tysiąc".to_string());
        } else {
            parts.extend(under1000(thousands).iter().map(|s| s.to_string()));
            let last_two = thousands % 100;
            let last = thousands % 10;
            if (12..=14).contains(&last_two) {
                parts.push("tysięcy".to_string());
            } else if (2..=4).contains(&last) {
                parts.push("tysiące".to_string());
            } else {
                parts.push("tysięcy".to_string());
            }
        }
    }
    parts.extend(under1000(value % 1000).iter().map(|s| s.to_string()));
    Some(parts.join(" "))
}

/// Spelling `R2` character by character is how a Polish reader says it; doing
/// the same to an eleven-character identifier is a wall of letter names nobody
/// follows. Past this the token is left written.
const MAX_SPELLED_CODE: usize = 8;

fn spelled_code_token(word: &str) -> Option<String> {
    let has_letter = word.chars().any(|c| c.is_alphabetic());
    let has_digit = word.chars().any(is_decimal_digit);
    if !(has_letter && has_digit) {
        return None;
    }
    // All or nothing. Skipping a character with no letter name turns
    // `Müller123` into *em el el e er jeden dwa* — the `ü` gone, a name
    // changed rather than mispronounced; and an eight-character cap that truncates
    // instead of refusing drops the last digits of `żelazny2024`. A token half-read
    // is worse than one left written, because the listener cannot tell that anything
    // was dropped.
    if word.chars().count() > MAX_SPELLED_CODE {
        return None;
    }
    let mut parts = Vec::new();
    for c in word.chars() {
        if let Some(d) = c.to_digit(10) {
            parts.push(DIGIT_WORDS[d as usize].to_string());
        } else {
            let s = c.to_lowercase().to_string();
            let (_, name) = LETTER_NAMES.iter().find(|(l, _)| *l == s)?;
            parts.push((*name).to_string());
        }
    }
    if parts.is_empty() {
        return None;
    }
    Some(parts.join(" "))
}

fn match_case(original: &str, respelled: &str) -> String {
    let first = original.chars().next().unwrap_or(' ');
    if !first.is_uppercase() {
        return respelled.to_string();
    }
    let mut r = respelled.to_string();
    if let Some(c) = r.chars().next() {
        let up = c.to_uppercase().to_string();
        r.replace_range(0..c.len_utf8(), &up);
    }
    r
}

fn respelled(word: &str) -> String {
    // No acronym branch here any more. `crate::letters::spell_acronyms` owns
    // that decision for all twelve languages and takes it earlier in the funnel,
    // where the surrounding capitals are still visible — this pass sees one word
    // at a time and so could not tell an initialism from a shout. It spelled
    // "THIS IS FINE" as te-ha-i-es i-es ef-i-en-e, and "CIA CIA" as ce-i-a
    // ce-i-a where the earlier pass had already decided that a run of capitals
    // is emphasis. `spelled_acronym` stays: the English-run test below still
    // asks it whether a word is an acronym, which is a different question from
    // spelling one.
    if let Some(c) = spelled_code_token(word) {
        return c;
    }
    let lower = word.to_lowercase();
    if let Some(hit) = lookup(&lower) {
        return match_case(word, &hit);
    }
    // Digits-only tokens: cardinal words when sane, digit-by-digit when weird.
    let all_digits = word.chars().all(is_decimal_digit);
    if all_digits {
        if let Some(cardinal) = number_words(word) {
            return cardinal;
        }
        let parts: Vec<&str> = word
            .chars()
            .filter_map(|c| c.to_digit(10).map(|d| DIGIT_WORDS[d as usize]))
            .collect();
        return parts.join(" ");
    }
    // Nothing under three letters declines from a dictionary stem.
    if lower.chars().count() <= 3 {
        return word.to_string();
    }
    // A word the Polish frequency list knows is POLISH: hands off.
    if POLISH_SET.contains(&lower) {
        return word.to_string();
    }
    // Inflected: longest dictionary stem + a known Polish ending.
    let runes: Vec<char> = lower.chars().collect();
    for cut in (2..runes.len()).rev() {
        let stem: String = runes[..cut].iter().collect();
        let mut suffix: String = runes[cut..].iter().collect();
        if suffix.starts_with('\'') || suffix.starts_with('’') {
            suffix.remove(0);
        }
        let base = lookup(&stem).or_else(|| lookup(&format!("{stem}e"))); // silent-e: "update"→"updatem"
        if let Some(mut base) = base {
            if ENDINGS_SET.contains(suffix.as_str()) {
                // The respelling's trailing vowel folds into a vowel-initial ending.
                let base_last = base.chars().last().unwrap_or(' ');
                let suf_first = suffix.chars().next().unwrap_or(' ');
                if "aeiouy".contains(base_last) && "aeiouy".contains(suf_first) {
                    base.pop();
                }
                return match_case(word, &format!("{base}{suffix}"));
            }
        }
    }
    word.to_string()
}

fn respell_symbols(text: &str) -> String {
    let mut out = text.to_string();
    for (re, replacement) in RESPEL_SYMBOL_RES.iter() {
        out = re.replace_all(&out, *replacement).to_string();
    }
    out
}

fn respell_phrases(text: &str) -> String {
    let mut out = text.to_string();
    for (phrase, spoken) in PHRASES {
        let re = Regex::new(&format!("(?i){}", regex::escape(phrase))).unwrap();
        out = re.replace_all(&out, spoken).to_string();
    }
    out
}

fn respell_words(text: &str) -> String {
    let mut words: Vec<String> = Vec::new();
    let mut seps: Vec<String> = vec![String::new()];
    let mut in_word = false;
    for c in text.chars() {
        if c.is_alphabetic() || c.is_numeric() || c == '\'' || c == '’' {
            if !in_word {
                words.push(String::new());
                in_word = true;
            }
            words.last_mut().unwrap().push(c);
        } else {
            if in_word {
                seps.push(String::new());
                in_word = false;
            }
            seps.last_mut().unwrap().push(c);
        }
    }
    if in_word {
        seps.push(String::new());
    }

    let is_digits = |w: &str| !w.is_empty() && w.chars().all(is_decimal_digit);

    // A RUN of English words is a quotation, not code-switching: four or more
    // in a row read better with the real English lexicon. Short bursts stay.
    let is_english: Vec<bool> = words
        .iter()
        .map(|word| {
            let lower = word.to_lowercase();
            spelled_acronym(word).is_none()
                && !KEEP_POLISH_SET.contains(&lower)
                && !POLISH_FUNCTION_SET.contains(&lower)
                && (lookup(&lower).is_some() || is_english_word(&lower))
        })
        .collect();

    let mut out = seps[0].clone();
    let mut i = 0;
    while i < words.len() {
        // The whole run of digit groups is measured before any of it is read,
        // because the decision belongs to the run and not to its first pair.
        // Two groups is a decimal — "dwa przecinek pięć". Three or more is a
        // version, an address or a date, and is left exactly as written.
        //
        // Reading only the first pair turns "192.168.0.1" into "sto
        // dziewięćdziesiąt dwa przecinek jeden sześć osiem" with ".0.1"
        // trailing behind it, and skipping just that pair moves the same
        // mistake one group along; Python's `expand_numbers` refuses these by
        // the same rule, and this reader has to agree with it.
        //
        // The same run when it starts with a token that has a letter in it: `v1.2.3`
        // collects as ["v1", "2", "3"] and the branch below only starts on a pure-digit
        // group, so the chain is never measured and the version comes out "fał jeden.dwa
        // przecinek trzy".
        if spelled_code_token(&words[i]).is_some() {
            let mut end = i;
            while end + 1 < words.len()
                && (seps[end + 1] == "." || seps[end + 1] == ",")
                && (is_digits(&words[end + 1]) || spelled_code_token(&words[end + 1]).is_some())
            {
                end += 1;
            }
            if end > i {
                for k in i..=end {
                    out.push_str(&words[k]);
                    out.push_str(&seps[k + 1]);
                }
                i = end + 1;
                continue;
            }
        }

        if is_digits(&words[i]) {
            let mut end = i;
            while end + 1 < words.len()
                && is_digits(&words[end + 1])
                && (seps[end + 1] == "." || seps[end + 1] == ",")
            {
                end += 1;
            }
            let groups = end - i + 1;
            if groups >= 3 {
                for (k, word) in words.iter().enumerate().take(end + 1).skip(i) {
                    out.push_str(word);
                    out.push_str(seps.get(k + 1).map_or("", String::as_str));
                }
                i = end + 1;
                continue;
            }
            if groups == 2 {
                let whole = number_words(&words[i]).unwrap_or_else(|| words[i].clone());
                let frac: Vec<&str> = words[i + 1]
                    .chars()
                    .filter_map(|c| c.to_digit(10).map(|d| DIGIT_WORDS[d as usize]))
                    .collect();
                let next_sep = seps.get(i + 2).cloned().unwrap_or_default();
                out.push_str(&whole);
                out.push_str(" przecinek ");
                out.push_str(&frac.join(" "));
                out.push_str(&next_sep);
                i += 2;
                continue;
            }
        }
        if is_english[i] {
            let mut j = i;
            while j < words.len() && is_english[j] {
                j += 1;
            }
            if j - i >= 4 {
                // Inside a detected English span every word transliterates,
                // gate ignored — "brown" alone stays Polish, "brown" inside
                // "the quick brown fox" becomes "brałn".
                for k in i..j {
                    let lower = words[k].to_lowercase();
                    let hit = LEXICON_MAP
                        .get(&lower)
                        .or_else(|| respell_all().get(&lower))
                        .cloned();
                    let spoken = hit.unwrap_or_else(|| words[k].clone());
                    out.push_str(&match_case(&words[k], &spoken));
                    out.push_str(&seps[k + 1]);
                }
                i = j;
                continue;
            }
        }
        out.push_str(&respelled(&words[i]));
        out.push_str(&seps[i + 1]);
        i += 1;
    }
    out
}

/// Respell `text` for the given language. Only Polish has a lexicon today;
/// every other language returns the text untouched.
pub fn lexical_respelling(text: &str, language_id: &str) -> String {
    // Lowercased here too: `lexical_respelling` is public and callable on its
    // own, so it cannot rely on `speech_text` having normalised the tag.
    if language_id.to_lowercase() != "pl" {
        return text.to_string();
    }
    let out = respell_symbols(text);
    let out = respell_phrases(&out);
    respell_words(&out)
}
